// Shared busy states. Unknown-duration requests are indeterminate, never fake percentages.
function uiEscape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function loadingView(title='Loading your workspace',detail='Please wait while we get everything ready.',compact=false,steps=[],current=0){return `<section class="loading-state ${compact?'loading-state-compact':''}" role="status" aria-live="polite"><div class="loading-brand-mark" aria-hidden="true"><img src="assets/brand/nextwork-icon.png" width="30" height="30" alt=""></div><div class="loading-content"><span class="section-label">WORKING ON IT</span><h2>${uiEscape(title)}</h2><p>${uiEscape(detail)}</p><div class="loading-track" role="progressbar" aria-label="${uiEscape(title)}" aria-valuetext="${uiEscape(detail)}"><span></span></div>${steps.length?`<ol class="loading-steps">${steps.map((step,i)=>`<li class="${i<current?'complete':i===current?'current':''}"><span>${i<current?'✓':i+1}</span>${uiEscape(step)}</li>`).join('')}</ol>`:''}<small>We’ll show the result as soon as it’s ready.</small></div></section>`}
function inlineLoading(text='Loading…'){return `<div class="inline-loading" role="status"><span>${uiEscape(text)}</span><div class="loading-track" role="progressbar" aria-label="${uiEscape(text)}"><span></span></div></div>`}
function showBusyAt(id,title,detail){const el=document.getElementById(id);if(el){el.innerHTML=loadingView(title,detail,true);el.hidden=false}}
function clearBusyAt(id){const el=document.getElementById(id);if(el){el.innerHTML='';el.hidden=true}}
